103: def chenh_sau_chot(chup: dict[str, Any], song: dict[str, Any]) -> dict[str, int]:
104:     """Số "phát sinh sau khi chốt" của đúng ca: sống − chụp (thu / huỷ / hoàn /
105:     thực thu). Toàn 0 = không có gì sau chốt. Thuần."""
106:     a = chup.get("tong") or {}
107:     b = song.get("tong") or {}
108:     return {
109:         k: int(b.get(k) or 0) - int(a.get(k) or 0)
110:         for k in ("thu", "huy", "hoan", "thuc_thu")
111:     }

